    width: 100%;
    padding: 20px 24px;
    background: none;
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    color: var(--color-text-primary);
    font-size: 1.1rem;
    font-weight: 600;
    transition: all var(--transition-duration) ease-out;
    text-align: left;
}

.faq-question:hover {
    color: var(--color-accent);
}

.faq-question:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: -2px;
}

.faq-question:active {
    transform: scale(0.99);
}

.question-text {
    flex: 1;
    text-align: left;
}

.toggle-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border-radius: 6px;
